package com.srenterprises.entity;
import jakarta.persistence.*; import java.time.*; import java.util.*; import java.math.*;
@Entity @Table(name="products") public class Product { @Id public UUID id=UUID.randomUUID(); @Column(nullable=false) public String name; @Column(nullable=false,unique=true) public String slug; @Column(nullable=false,unique=true) public String sku; @Column(columnDefinition="TEXT") public String description; @Column(nullable=false) public BigDecimal price; @Column(name="discount_price") public BigDecimal discountPrice; @Enumerated(EnumType.STRING) public ProductStatus status=ProductStatus.DRAFT; public boolean featured; @ManyToOne public Category category; @Column(name="created_at") public Instant createdAt=Instant.now(); @Column(name="updated_at") public Instant updatedAt=Instant.now(); }
